class_name SaveSystem
extends Node

const SAVE_PATH: String = "user://mini_save.json"


static func save_state(player: Node2D) -> void:
	var data: Dictionary = {
		"player": {
			"x": player.global_position.x,
			"y": player.global_position.y,
			"lives": int(player.get("lives")) if player.get("lives") != null else 3
		}
	}
	var file := FileAccess.open(SAVE_PATH, FileAccess.WRITE)
	if file != null:
		file.store_string(JSON.stringify(data))
		file.close()


static func load_state(player: Node2D) -> void:
	if not FileAccess.file_exists(SAVE_PATH):
		return
	var file := FileAccess.open(SAVE_PATH, FileAccess.READ)
	if file == null:
		return
	var text := file.get_as_text()
	file.close()
	var json := JSON.new()
	if json.parse(text) != OK:
		return
	var data: Dictionary = json.data
	if data.has("player"):
		var p: Dictionary = data["player"]
		player.global_position = Vector2(float(p.get("x", 0.0)), float(p.get("y", 0.0)))
		if player.get("lives") != null:
			player.set("lives", int(p.get("lives", 3)))

extends CharacterBody2D

var lives: int = 3
var coins: int = 0
var alert_level: int = 1


func take_hit() -> void:
	lives = maxi(0, lives - 1)


func add_coins(amount: int) -> void:
	coins += amount


func set_alert_level(level: int) -> void:
	alert_level = level

class_name SaveSystem
extends Node

const SAVE_PATH: String = "user://mini_save.json"


static func save_state(player: Node2D) -> void:
	var data: Dictionary = {
		"player": {
			"x": player.global_position.x,
			"y": player.global_position.y,
			"lives": int(player.get("lives")) if player.get("lives") != null else 3,
			"coins": int(player.get("coins")) if player.get("coins") != null else 0,
			"alert_level": int(player.get("alert_level")) if player.get("alert_level") != null else 1
		}
	}
	var file := FileAccess.open(SAVE_PATH, FileAccess.WRITE)
	if file != null:
		file.store_string(JSON.stringify(data))
		file.close()


static func load_state(player: Node2D) -> void:
	if not FileAccess.file_exists(SAVE_PATH):
		return
	var file := FileAccess.open(SAVE_PATH, FileAccess.READ)
	if file == null:
		return
	var text := file.get_as_text()
	file.close()
	var json := JSON.new()
	if json.parse(text) != OK:
		return
	var data: Dictionary = json.data
	if data.has("player"):
		var p: Dictionary = data["player"]
		player.global_position = Vector2(float(p.get("x", 0.0)), float(p.get("y", 0.0)))
		if player.get("lives") != null:
			player.set("lives", int(p.get("lives", 3)))
		if player.get("coins") != null:
			player.set("coins", int(p.get("coins", 0)))
		if player.get("alert_level") != null:
			player.set("alert_level", int(p.get("alert_level", 1)))
